param([switch]$KeepInfra)
$ErrorActionPreference='Stop'
$paymentRoot=[IO.Path]::GetFullPath((Split-Path -Parent $PSScriptRoot));$paymentRuntime=Join-Path $paymentRoot '.runtime';$metadata=Join-Path $paymentRuntime 'processes.json'
if(Test-Path -LiteralPath $metadata){$meta=Get-Content -LiteralPath $metadata -Raw | ConvertFrom-Json;if($meta.root -eq $paymentRoot){$p=Get-CimInstance Win32_Process -Filter ('ProcessId = '+$meta.gateway);if($p -and $p.Name -eq 'node.exe' -and $p.CommandLine -match 'scripts[\\/]gateway\.mjs' -and [Math]::Abs((([datetime]$meta.startedAt).ToUniversalTime()-$p.CreationDate.ToUniversalTime()).TotalSeconds) -lt 120){Stop-Process -Id $p.ProcessId -ErrorAction SilentlyContinue}}}
Get-CimInstance Win32_Process -Filter "name = 'java.exe'" | Where-Object {$_.CommandLine -and $_.CommandLine.Contains((Join-Path $paymentRuntime 'app-'))} | ForEach-Object {Stop-Process -Id $_.ProcessId -ErrorAction SilentlyContinue}
Get-CimInstance Win32_Process -Filter "name = 'node.exe'" | Where-Object {$_.CommandLine -and $_.CommandLine.Contains((Join-Path $paymentRoot 'psp/server.mjs'))} | ForEach-Object {Stop-Process -Id $_.ProcessId -ErrorAction SilentlyContinue}
if(-not $KeepInfra){$owner=Get-NetTCPConnection -State Listen -LocalPort 56489 -ErrorAction SilentlyContinue | Select-Object -First 1;if($owner){$p=Get-CimInstance Win32_Process -Filter ('ProcessId = '+$owner.OwningProcess);if($p.ExecutablePath -and $p.ExecutablePath.StartsWith($paymentRuntime+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){& (Join-Path $paymentRuntime 'redis/Redis-7.4.3-Windows-x64-cygwin/redis-cli.exe') -p 56489 SHUTDOWN SAVE}};foreach($cluster in @('merchant','psp')){$data=Join-Path $paymentRuntime ('pg-'+$cluster);if(Test-Path -LiteralPath (Join-Path $data 'postmaster.pid')){& (Join-Path $paymentRuntime 'postgres/bin/pg_ctl.exe') -D $data -m fast -w -t 15 stop}}}
Write-Output 'Owned payment processes stopped; independent project data retained.'
